            if nbytes == 1:
                self.regs[addr] = (self.regs[addr] & 0x00FF) | ((data & 0xFF) << 8)
            else:
                self.regs[addr] = data
        else:
            raise ValueError(f"Invalid register address: 0x{addr:02X}")
